      :f))]));
  return Object.freeze({...priority,...rows,networkScope:'REPORTED_DEFINITION_ONLY',priorityDigest:digest({previous:priority.priorityDigest,...rows,networkScope:'REPORTED_DEFINITION_ONLY'})});
}

